{
  "name": "CAT BKN Simulator Generator",
  "description": "A CPNS SKD question generator that simulates the official CAT BKN exam format using Gemini AI to create TWK, TIU, and TKP questions from news topics."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface QuestionMeta {
  news_topic: string;
  question_type: string;
  stimulus_excerpt: string;
}

export interface QuestionOptions {
  A: string;
  B: string;
  C: string;
  D: string;
  E: string;
}

export interface TkpPoints {
  A: number;
  B: number;
  C: number;
  D: number;
  E: number;
}

export interface AnswerKey {
  correct_option: string; // "A" | "B" | "C" | "D" | "E"
  tkp_points: TkpPoints | null;
}

export interface QuestionContent {
  category: 'TWK' | 'TIU' | 'TKP';
  topic: string;
  subtopic: string;
  question_text: string;
  options: QuestionOptions;
  answer_key: AnswerKey;
  explanation: string;
}

export interface GeneratedQuestion {
  meta: QuestionMeta;
  content: QuestionContent;
}

export enum AppState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  QUESTION = 'QUESTION',
  RESULT = 'RESULT',
  ERROR = 'ERROR'
}

import React, { useState } from 'react';

interface InputSectionProps {
  onGenerate: (text: string) => void;
  isLoading: boolean;
}

const InputSection: React.FC<InputSectionProps> = ({ onGenerate, isLoading }) => {
  const [text, setText] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim()) {
      onGenerate(text);
    }
  };

  const handlePasteSample = () => {
    const sample = "Pemerintah berencana menerapkan sistem identitas digital terpadu untuk seluruh layanan publik mulai tahun depan. Langkah ini diharapkan dapat memangkas birokrasi, namun memicu kekhawatiran terkait keamanan data pribadi warga negara di tengah maraknya kasus kebocoran data.";
    setText(sample);
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-2xl mx-auto border-t-4 border-blue-600">
      <h2 className="text-xl font-bold text-gray-800 mb-4">Input Berita / Topik</h2>
      <p className="text-sm text-gray-600 mb-4">
        Masukkan potongan berita, artikel, atau topik terkini untuk dijadikan bahan soal SKD (TWK, TIU, atau TKP).
      </p>

      <form onSubmit={handleSubmit} className="space-y-4">
        <textarea
          className="w-full h-40 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition resize-none font-sans text-gray-700"
          placeholder="Contoh: Pemerintah meresmikan bendungan baru di Jawa Barat untuk mengantisipasi banjir tahunan..."
          value={text}
          onChange={(e) => setText(e.target.value)}
          disabled={isLoading}
        ></textarea>

        <div className="flex justify-between items-center">
          <button
            type="button"
            onClick={handlePasteSample}
            className="text-sm text-blue-600 hover:text-blue-800 font-medium disabled:opacity-50"
            disabled={isLoading}
          >
            Tempel Contoh Berita
          </button>

          <button
            type="submit"
            disabled={isLoading || !text.trim()}
            className={`px-6 py-2.5 rounded-md font-semibold text-white shadow-sm transition-all
              ${isLoading || !text.trim() 
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-blue-600 hover:bg-blue-700 active:transform active:scale-95'
              }`}
          >
            {isLoading ? (
              <span className="flex items-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Memproses...
              </span>
            ) : (
              'Buat Soal'
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default InputSection;

import React, { useState, useEffect } from 'react';
import { GeneratedQuestion } from '../types';

interface QuestionCardProps {
  data: GeneratedQuestion;
  onAnswer: (selectedOption: string) => void;
  onReset: () => void;
}

const QuestionCard: React.FC<QuestionCardProps> = ({ data, onAnswer, onReset }) => {
  const [selected, setSelected] = useState<string | null>(null);

  const { content, meta } = data;

  // Reset selection if data changes (though typically parent will unmount/remount)
  useEffect(() => {
    setSelected(null);
  }, [data]);

  const handleSubmit = () => {
    if (selected) {
      onAnswer(selected);
    }
  };

  const getCategoryColor = (cat: string) => {
    switch (cat) {
      case 'TWK': return 'bg-red-100 text-red-800 border-red-200';
      case 'TIU': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'TKP': return 'bg-green-100 text-green-800 border-green-200';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg border border-gray-200 overflow-hidden max-w-4xl mx-auto">
      {/* Header Bar */}
      <div className="bg-blue-600 text-white p-4 flex justify-between items-center">
        <div className="font-bold text-lg">SIMULASI CAT BKN</div>
        <div className="text-sm bg-blue-700 px-3 py-1 rounded">
          Sisa Waktu: --:--
        </div>
      </div>

      <div className="flex flex-col md:flex-row">
        {/* Left: Question Area */}
        <div className="flex-1 p-6 md:p-8">

          {/* Metadata Badges */}
          <div className="flex flex-wrap gap-2 mb-6">
            <span className={`px-2.5 py-0.5 rounded border text-xs font-bold ${getCategoryColor(content.category)}`}>
              {content.category}
            </span>
            <span className="px-2.5 py-0.5 rounded border bg-gray-100 text-gray-600 border-gray-200 text-xs font-medium">
              Topik: {content.topic}
            </span>
            <span className="px-2.5 py-0.5 rounded border bg-blue-50 text-blue-600 border-blue-100 text-xs font-medium">
              HOTS
            </span>
          </div>

          {/* Stimulus Box */}
          <div className="bg-gray-50 border-l-4 border-gray-400 p-4 mb-6 text-sm text-gray-700 italic">
            <h4 className="font-semibold text-gray-900 mb-1 not-italic text-xs uppercase tracking-wide">Stimulus Berita:</h4>
            "{meta.stimulus_excerpt}"
          </div>

          {/* Question Text */}
          <div className="text-lg text-gray-800 font-medium leading-relaxed mb-8">
            {content.question_text}
          </div>

          {/* Options */}
          <div className="space-y-3">
            {(Object.keys(content.options) as Array<keyof typeof content.options>).map((optKey) => (
              <label 
                key={optKey}
                className={`flex items-start p-4 rounded-lg border-2 cursor-pointer transition-all hover:bg-blue-50
                  ${selected === optKey 
                    ? 'border-blue-600 bg-blue-50' 
                    : 'border-gray-200 bg-white'
                  }`}
              >
                <input
                  type="radio"
                  name="option"
                  value={optKey}
                  checked={selected === optKey}
                  onChange={() => setSelected(optKey)}
                  className="hidden"
                />
                <div className={`flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-full border-2 mr-4 font-bold
                  ${selected === optKey 
                    ? 'bg-blue-600 border-blue-600 text-white' 
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }`}>
                  {optKey}
                </div>
                <div className="pt-0.5 text-gray-700">
                  {content.options[optKey]}
                </div>
              </label>
            ))}
          </div>
        </div>

        {/* Right/Bottom: Action Area (Simplified for Simulator feel) */}
      </div>

      {/* Footer Actions */}
      <div className="bg-gray-50 p-4 border-t border-gray-200 flex justify-between items-center">
        <button
          onClick={onReset}
          className="px-4 py-2 text-gray-600 font-medium hover:text-gray-800 transition"
        >
          &larr; Buat Soal Baru
        </button>
        <button
          onClick={handleSubmit}
          disabled={!selected}
          className={`px-8 py-2.5 rounded shadow-sm font-bold text-white transition-all
            ${!selected 
              ? 'bg-gray-300 cursor-not-allowed' 
              : 'bg-green-600 hover:bg-green-700 hover:shadow-md'
            }`}
        >
          Simpan dan Lanjutkan
        </button>
      </div>
    </div>
  );
};

export default QuestionCard;

import React from 'react';
import { GeneratedQuestion } from '../types';

interface ResultCardProps {
  data: GeneratedQuestion;
  userSelection: string;
  onReset: () => void;
}

const ResultCard: React.FC<ResultCardProps> = ({ data, userSelection, onReset }) => {
  const { content } = data;
  const isTKP = content.category === 'TKP';
  const correctOption = content.answer_key.correct_option;

  // Calculate Score/Points
  let userPoints = 0;
  let maxPoints = isTKP ? 5 : 5; // Standardizing standard questions to 5 for simplicity in display

  if (isTKP) {
    userPoints = content.answer_key.tkp_points?.[userSelection as keyof typeof content.answer_key.tkp_points] || 0;
  } else {
    userPoints = userSelection === correctOption ? 5 : 0;
  }

  const isPerfect = userPoints === 5;

  return (
    <div className="bg-white rounded-lg shadow-xl border border-gray-200 max-w-4xl mx-auto overflow-hidden animate-fade-in">
      <div className={`p-6 text-white text-center ${isPerfect ? 'bg-green-600' : 'bg-blue-600'}`}>
        <h2 className="text-2xl font-bold mb-1">Pembahasan Soal</h2>
        <p className="opacity-90">Kategori: {content.category}</p>
      </div>

      <div className="p-8">
        {/* Score Display */}
        <div className="flex flex-col items-center justify-center mb-8">
          <div className="text-sm text-gray-500 uppercase tracking-wider mb-2">Poin Anda</div>
          <div className={`text-5xl font-extrabold ${isPerfect ? 'text-green-600' : isTKP ? 'text-blue-600' : 'text-red-500'}`}>
            {userPoints} <span className="text-2xl text-gray-400 font-medium">/ 5</span>
          </div>
        </div>

        {/* Answer Review */}
        <div className="space-y-4 mb-8">
          {(Object.keys(content.options) as Array<keyof typeof content.options>).map((optKey) => {
            const isSelected = userSelection === optKey;
            const isCorrect = correctOption === optKey;

            // Logic for coloring the option
            let containerClass = "border-gray-200 bg-gray-50 opacity-60";
            let badgeClass = "bg-gray-200 text-gray-500";

            if (isTKP) {
              const points = content.answer_key.tkp_points?.[optKey];
              if (isSelected) {
                containerClass = "border-blue-500 bg-blue-50 ring-1 ring-blue-500 opacity-100";
                badgeClass = "bg-blue-600 text-white";
              } else if (points === 5) {
                containerClass = "border-green-500 bg-green-50 opacity-100";
                badgeClass = "bg-green-600 text-white";
              }
            } else {
              // TWK / TIU
              if (isCorrect) {
                containerClass = "border-green-500 bg-green-50 opacity-100";
                badgeClass = "bg-green-600 text-white";
              } else if (isSelected && !isCorrect) {
                containerClass = "border-red-500 bg-red-50 opacity-100";
                badgeClass = "bg-red-600 text-white";
              } else if (isSelected && isCorrect) {
                 containerClass = "border-green-500 bg-green-50 ring-1 ring-green-500 opacity-100";
              }
            }

            return (
              <div key={optKey} className={`flex items-center p-3 rounded-lg border ${containerClass}`}>
                <div className={`w-8 h-8 flex items-center justify-center rounded-full text-sm font-bold mr-3 ${badgeClass}`}>
                  {optKey}
                </div>
                <div className="flex-1 text-gray-800 text-sm md:text-base">
                  {content.options[optKey]}
                </div>
                {isTKP && (
                  <div className="ml-3 font-bold text-gray-500 text-sm">
                    {content.answer_key.tkp_points?.[optKey]} Poin
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Explanation Text */}
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
          <h3 className="font-bold text-yellow-800 mb-2 flex items-center">
            <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"/></svg>
            Kunci & Pembahasan
          </h3>
          <p className="text-gray-700 leading-relaxed whitespace-pre-wrap text-sm md:text-base">
            {content.explanation}
          </p>
        </div>
      </div>

      <div className="bg-gray-50 p-4 border-t border-gray-200 text-center">
        <button
          onClick={onReset}
          className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-8 rounded shadow transition-colors"
        >
          Buat Soal Berikutnya
        </button>
      </div>
    </div>
  );
};

export default ResultCard;

import React, { useState } from 'react';
import { generateQuestion } from './services/geminiService';
import { GeneratedQuestion, AppState } from './types';
import InputSection from './components/InputSection';
import QuestionCard from './components/QuestionCard';
import ResultCard from './components/ResultCard';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [questionData, setQuestionData] = useState<GeneratedQuestion | null>(null);
  const [userSelection, setUserSelection] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const handleGenerate = async (text: string) => {
    setAppState(AppState.LOADING);
    setErrorMsg('');
    try {
      const data = await generateQuestion(text);
      setQuestionData(data);
      setAppState(AppState.QUESTION);
    } catch (err: any) {
      setErrorMsg(err.message || 'Terjadi kesalahan saat membuat soal.');
      setAppState(AppState.ERROR);
    }
  };

  const handleAnswer = (option: string) => {
    setUserSelection(option);
    setAppState(AppState.RESULT);
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setQuestionData(null);
    setUserSelection('');
    setErrorMsg('');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 text-white py-4 px-6 shadow-md z-10 sticky top-0">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-500 rounded flex items-center justify-center font-bold text-lg">
              S
            </div>
            <div>
              <h1 className="font-bold text-lg leading-tight">CAT BKN Simulator</h1>
              <p className="text-xs text-gray-400">AI-Powered Question Generator</p>
            </div>
          </div>
          <div className="text-xs text-gray-400 hidden sm:block">
            Gemini 2.0 Flash Integration
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full p-4 md:p-8">

        {appState === AppState.IDLE && (
          <div className="animate-fade-in-up">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-extrabold text-gray-800 mb-3">
                Latihan SKD Berbasis Isu Terkini
              </h2>
              <p className="text-gray-600 max-w-2xl mx-auto">
                Mesin ini menggunakan AI untuk mengubah berita atau topik apa pun menjadi soal standar CAT CPNS (TWK, TIU, TKP) lengkap dengan pembahasan HOTS.
              </p>
            </div>
            <InputSection onGenerate={handleGenerate} isLoading={false} />

            {/* Features Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 text-center">
              <div className="p-4">
                <div className="w-12 h-12 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">W</div>
                <h3 className="font-bold text-gray-800">TWK (Wawasan Kebangsaan)</h3>
                <p className="text-sm text-gray-500 mt-2">Analisis pilar negara dan implementasi Pancasila dalam kasus nyata.</p>
              </div>
              <div className="p-4">
                <div className="w-12 h-12 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">I</div>
                <h3 className="font-bold text-gray-800">TIU (Intelegensia Umum)</h3>
                <p className="text-sm text-gray-500 mt-2">Logika verbal, numerik, dan penalaran analitis dari data berita.</p>
              </div>
              <div className="p-4">
                <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">K</div>
                <h3 className="font-bold text-gray-800">TKP (Karakteristik Pribadi)</h3>
                <p className="text-sm text-gray-500 mt-2">Studi kasus pelayanan publik dan profesionalisme ASN (BerAKHLAK).</p>
              </div>
            </div>
          </div>
        )}

        {appState === AppState.LOADING && (
          <div className="flex flex-col items-center justify-center h-64 animate-pulse">
            <div className="w-16 h-16 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin mb-4"></div>
            <p className="text-gray-600 font-medium">Sedang menganalisis berita...</p>
            <p className="text-xs text-gray-400 mt-2">AI sedang menyusun soal HOTS sesuai kisi-kisi SKD</p>
          </div>
        )}

        {appState === AppState.ERROR && (
          <div className="max-w-xl mx-auto text-center bg-red-50 p-8 rounded-lg border border-red-200">
            <div className="text-red-500 text-5xl mb-4">⚠️</div>
            <h3 className="text-xl font-bold text-red-800 mb-2">Terjadi Kesalahan</h3>
            <p className="text-red-600 mb-6">{errorMsg}</p>
            <button 
              onClick={handleReset}
              className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition"
            >
              Coba Lagi
            </button>
          </div>
        )}

        {appState === AppState.QUESTION && questionData && (
          <QuestionCard 
            data={questionData} 
            onAnswer={handleAnswer} 
            onReset={handleReset}
          />
        )}

        {appState === AppState.RESULT && questionData && (
          <ResultCard 
            data={questionData} 
            userSelection={userSelection} 
            onReset={handleReset}
          />
        )}

      </main>

      <footer className="bg-gray-100 py-6 text-center text-gray-500 text-sm border-t border-gray-200 mt-auto">
        &copy; {new Date().getFullYear()} Simulator SKD AI. Bukan aplikasi resmi BKN.
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Schema } from "@google/genai";
import { GeneratedQuestion } from "../types";

const SYSTEM_PROMPT = `# SYSTEM PROMPT — CPNS SKD QUESTION GENERATOR (CAT BKN SIMULATOR)

## PERAN & TUJUAN
Anda adalah **Mesin Simulasi CAT BKN (SKD CPNS)** yang bertugas membuat **1 (satu) soal latihan berkualitas tinggi** berbasis **teks berita/topik terkini** yang diberikan pengguna.

Berita berfungsi sebagai **stimulus/konteks**, bukan “jawaban jadi”.
- **TWK:** Berita → studi kasus penerapan nilai kebangsaan.
- **TIU:** Berita → sumber data/teks untuk penalaran logis-verbal-numerik.
- **TKP:** Berita → skenario dilema kerja/pelayanan publik yang relevan untuk ASN.

---

## ATURAN GLOBAL (WAJIB)
1. **Output hanya JSON valid**: tidak ada markdown, tidak ada prosa pembuka/penutup, tidak ada komentar. Output harus **mulai dengan \`{\` dan berakhir dengan \`}\`**.
2. **Bahasa**: Bahasa Indonesia baku, gaya soal resmi (netral, birokratis, presisi).
3. **Satu soal saja** per respons.
4. **HOTS**: Soal harus menuntut analisis (menimbang opsi, menarik kesimpulan, multi-langkah), bukan sekadar definisi/hafalan.
5. **Keterikatan stimulus**: Informasi yang diperlukan untuk menjawab harus ada di stem (kutipan/angka dari berita). Jangan mengandalkan fakta eksternal yang tidak tersurat di stimulus.
6. **Anti-ambigu**:
   - **TWK/TIU**: tepat **1** opsi benar. Opsi lain harus salah **dengan alasan yang jelas**.
   - **TIU numerik**: cantumkan ketentuan pembulatan bila perlu. Hindari dua opsi yang setara karena pembulatan.
7. **Distractor (opsi salah) wajib masuk akal**:
   - **TWK/TIU**: salahnya karena konsep/penalaran yang meleset, bukan karena “asal beda”.
   - **TIU numerik**: distraktor sebaiknya merepresentasikan kesalahan umum (salah basis persen, salah urutan operasi, salah selisih vs rasio, dsb.).
   - Dilarang: “Semua jawaban benar/salah”, “Tidak ada jawaban”, opsi bercanda, opsi identik/nyaris identik.
8. **TKP**: semua opsi harus terdengar **wajar/positif-netral** (tidak “jahat” terang-terangan). Perbedaan kualitas terlihat dari **proaktivitas, sistemik, integritas, dan orientasi pelayanan**.
9. **Keamanan & netralitas**: jangan memproduksi ujaran kebencian, fitnah, atau ajakan kekerasan. Jika berita sensitif, gunakan framing profesional/administratif.

---

## PEMILIHAN KATEGORI (TWK / TIU / TKP)
Pilih kategori paling “alami” dari isi berita:
- **TIU** bila berita memuat **angka/target/persentase/anggaran/timeline** yang bisa diolah.
- **TKP** bila berita memuat **insiden layanan publik, keluhan warga, gangguan sistem, koordinasi lintas unit, tekanan waktu, krisis operasional**.
- **TWK** bila berita memuat **kebijakan publik, dinamika sosial, hoaks, konflik kepentingan, persatuan, hukum/ketertiban, etika bernegara**.

Jika berita minim angka dan tidak memadai untuk TIU numerik, **jangan memaksakan TIU**—pilih TWK/TKP.

---

## I. TWK — MATRKS LOGIKA & BATASAN
**Tujuan TWK**: menguji penerapan nilai kebangsaan dalam konteks, bukan hafalan tanggal/nama.

**Ruang lingkup yang boleh dipakai (pilih salah satu sebagai \`topic\` TWK):**
1. Nasionalisme & Persatuan
2. Integritas & Anti-Korupsi
3. Bela Negara (fisik/nonfisik; termasuk literasi digital)
4. Pilar Negara (Pancasila, UUD 1945, NKRI, Bhinneka Tunggal Ika)
5. Bahasa Indonesia (gagasan utama, kalimat efektif, ketepatan diksi) berbasis kutipan stimulus

**Transformasi yang dianjurkan (contoh pola):**
- Berita tentang protes/kebijakan → uji prinsip musyawarah, ketertiban umum, partisipasi warga, dan etika demokrasi Pancasila.
- Berita tentang hoaks/disinformasi → uji bela negara nonfisik (literasi digital), persatuan, dan tanggung jawab warga dalam ruang publik.

**Catatan akurasi**: Bila menyebut pasal/ayat UUD 1945, pastikan tidak mengada-ada. Jika ragu, gunakan formulasi umum “ketentuan UUD 1945 tentang …” tanpa nomor pasal.

---

## II. TIU — MATRKS LOGIKA & BATASAN
**Tujuan TIU**: penalaran verbal, logika, dan numerik berbasis stimulus.

**Pilih salah satu sebagai \`topic\` TIU:**
1. Silogisme / Kesimpulan Logis (berdasarkan 2–3 premis dari stimulus)
2. Numerik (persentase, rasio, rata-rata, selisih, proyeksi sederhana)
3. Analogi Verbal (kata/frasa relevan dari stimulus)
4. Pemahaman Bacaan (inferensi, simpulan, tujuan kebijakan) *hanya jika stimulus cukup jelas*

**Aturan TIU numerik (wajib bila memilih Numerik):**
- Cantumkan semua angka yang diperlukan di soal.
- Pastikan hasilnya unik dan cocok dengan tepat satu opsi.
- Jika membutuhkan pembulatan, nyatakan: “dibulatkan ke …”.

---

## III. TKP — MATRKS LOGIKA BERAKHLAK
**Tujuan TKP**: mengukur perilaku kerja ASN selaras nilai **BerAKHLAK**:
- **Berorientasi Pelayanan**, **Akuntabel**, **Kompeten**, **Harmonis**, **Loyal**, **Adaptif**, **Kolaboratif**.

**Pilih salah satu sebagai \`topic\` TKP:**
1. Pelayanan Publik & Penanganan Keluhan
2. Jejaring Kerja & Koordinasi
3. Profesionalisme & Disiplin
4. Adaptasi TIK / Perubahan Proses
5. Sosial Budaya & Keberagaman
6. Pencegahan Radikalisme (pendekatan persuasif, prosedural, menjaga harmoni)

**Skoring TKP (wajib dan eksplisit):**
- Buat \`tkp_points\` berisi **A–E** dengan nilai **1–5** (integer).
- Harus ada **tepat satu** opsi bernilai **5** (paling ideal) dan tepat satu opsi bernilai **1** (paling lemah).
- \`correct_option\` untuk TKP adalah opsi dengan nilai **5**.

**Ciri opsi:**
- **5**: proaktif, sistemik, melibatkan pihak terkait, berbasis data, menjaga integritas, fokus layanan publik, selaras prosedur namun adaptif.
- **4**: kuat secara prosedural dan cepat, namun kurang inisiatif perbaikan sistem.
- **3**: menyelesaikan tugas minimum, cenderung reaktif.
- **2**: pasif/menunggu, kontribusi terbatas.
- **1**: menghindar, melempar tanggung jawab (tetap ditulis halus dan realistis, bukan “jahat”).

---

## SKEMA OUTPUT JSON (WAJIB PERSIS STRUKTURNYA)
- Gunakan **double quotes** untuk semua string.
- Jangan pakai trailing comma.
- Semua field harus ada. Jika tidak relevan, isi dengan \`null\` (bukan string "null").

\`\`\`json
{
  "meta": {
    "news_topic": "Ringkasan topik berita (maks 5 kata)",
    "question_type": "HOTS",
    "stimulus_excerpt": "Kutip 1–2 kalimat inti dari berita atau parafrase ketat (maks 300 karakter)."
  },
  "content": {
    "category": "TWK",
    "topic": "string dari daftar topik sesuai kategori",
    "subtopic": "konsep spesifik yang diuji",
    "question_text": "Stem soal lengkap (sertakan data/ketentuan penting agar mandiri).",
    "options": {
      "A": "teks opsi A",
      "B": "teks opsi B",
      "C": "teks opsi C",
      "D": "teks opsi D",
      "E": "teks opsi E"
    },
    "answer_key": {
      "correct_option": "A",
      "tkp_points": null
    },
    "explanation": "Uraian alasan: untuk TWK/TIU jelaskan mengapa benar & mengapa distraktor keliru; untuk TKP jelaskan logika skoring 1–5 per opsi dan kaitkan dengan BerAKHLAK."
  }
}
\`\`\`
`;

