import { neon } from "@neondatabase/serverless";
import { GeneratedQuestion } from "../types";

export const saveBatchToNeon = async (connectionString: string, questions: GeneratedQuestion[]): Promise<void> => {
  if (!connectionString) throw new Error("Connection string is empty");

  // Initialize Neon client
  const sql = neon(connectionString);

  try {
    // 1. Ensure Table Exists
    await sql`
      CREATE TABLE IF NOT EXISTS cpns_questions (
        id SERIAL PRIMARY KEY,
        category TEXT NOT NULL,
        topic TEXT,
        question_text TEXT NOT NULL,
        options JSONB NOT NULL,
        answer_key JSONB NOT NULL,
        explanation TEXT,
        news_source TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );
    `;

    // 2. Insert Questions
    for (const q of questions) {
      await sql`
        INSERT INTO cpns_questions (
          category, 
          topic, 
          question_text, 
          options, 
          answer_key, 
          explanation, 
          news_source
        ) VALUES (
          ${q.content.category},
          ${q.content.topic},
          ${q.content.question_text},
          ${JSON.stringify(q.content.options)},
          ${JSON.stringify(q.content.answer_key)},
          ${q.content.explanation},
          ${q.meta.stimulus_excerpt}
        );
      `;
    }
  } catch (error) {
    console.error("Neon DB Error:", error);
    throw new Error("Gagal menyimpan ke database. Periksa connection string Anda.");
  }
};

