                <div className={`flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-full border-2 mr-4 font-bold
                  ${selected === optKey 
                    ? 'bg-blue-600 border-blue-600 text-white' 
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }`}>
                  {optKey}
                </div>
                <div className="pt-0.5 text-gray-700">
                  {content.options[optKey]}
                </div>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Footer Actions */}
      <div className="bg-gray-50 p-4 border-t border-gray-200 flex justify-between items-center">
        <button
          onClick={onReset}
          className="px-4 py-2 text-gray-600 font-medium hover:text-gray-800 transition"
        >
          &larr; Batal & Kembali
        </button>
        <button
          onClick={handleSubmit}
          disabled={!selected}
          className={`px-8 py-2.5 rounded shadow-sm font-bold text-white transition-all
            ${!selected 
              ? 'bg-gray-300 cursor-not-allowed' 
              : 'bg-green-600 hover:bg-green-700 hover:shadow-md'
            }`}
        >
          Kunci Jawaban
        </button>
      </div>
    </div>
  );
};

export default QuestionCard;

import React from 'react';
import { GeneratedQuestion } from '../types';

interface ResultCardProps {
  data: GeneratedQuestion;
  userSelection: string;
  isLastQuestion: boolean;
  onNext: () => void;
  onReset: () => void;
}

const ResultCard: React.FC<ResultCardProps> = ({ data, userSelection, isLastQuestion, onNext, onReset }) => {
  const { content } = data;
  const isTKP = content.category === 'TKP';
  const correctOption = content.answer_key.correct_option;

  // Calculate Score/Points
  let userPoints = 0;

  if (isTKP) {
    userPoints = content.answer_key.tkp_points?.[userSelection as keyof typeof content.answer_key.tkp_points] || 0;
  } else {
    userPoints = userSelection === correctOption ? 5 : 0;
  }

  const isPerfect = userPoints === 5;

  return (
    <div className="bg-white rounded-lg shadow-xl border border-gray-200 max-w-4xl mx-auto overflow-hidden animate-fade-in">
      <div className={`p-6 text-white text-center ${isPerfect ? 'bg-green-600' : 'bg-blue-600'}`}>
        <h2 className="text-2xl font-bold mb-1">Pembahasan Soal</h2>
        <p className="opacity-90">Kategori: {content.category}</p>
      </div>

      <div className="p-8">
        {/* Score Display */}
        <div className="flex flex-col items-center justify-center mb-8">
          <div className="text-sm text-gray-500 uppercase tracking-wider mb-2">Poin Anda</div>
          <div className={`text-5xl font-extrabold ${isPerfect ? 'text-green-600' : isTKP ? 'text-blue-600' : 'text-red-500'}`}>
            {userPoints} <span className="text-2xl text-gray-400 font-medium">/ 5</span>
          </div>
        </div>

        {/* Answer Review */}
        <div className="space-y-4 mb-8">
          {(Object.keys(content.options) as Array<keyof typeof content.options>).map((optKey) => {
            const isSelected = userSelection === optKey;
            const isCorrect = correctOption === optKey;

            // Logic for coloring the option
            let containerClass = "border-gray-200 bg-gray-50 opacity-60";
            let badgeClass = "bg-gray-200 text-gray-500";

            if (isTKP) {
              const points = content.answer_key.tkp_points?.[optKey];
              if (isSelected) {
                containerClass = "border-blue-500 bg-blue-50 ring-1 ring-blue-500 opacity-100";
                badgeClass = "bg-blue-600 text-white";
              } else if (points === 5) {
                containerClass = "border-green-500 bg-green-50 opacity-100";
                badgeClass = "bg-green-600 text-white";
              }
            } else {
              // TWK / TIU
              if (isCorrect) {
                containerClass = "border-green-500 bg-green-50 opacity-100";
                badgeClass = "bg-green-600 text-white";
              } else if (isSelected && !isCorrect) {
                containerClass = "border-red-500 bg-red-50 opacity-100";
                badgeClass = "bg-red-600 text-white";
              } else if (isSelected && isCorrect) {
                 containerClass = "border-green-500 bg-green-50 ring-1 ring-green-500 opacity-100";
              }
            }

            return (
              <div key={optKey} className={`flex items-center p-3 rounded-lg border ${containerClass}`}>
                <div className={`w-8 h-8 flex items-center justify-center rounded-full text-sm font-bold mr-3 ${badgeClass}`}>
                  {optKey}
                </div>
                <div className="flex-1 text-gray-800 text-sm md:text-base">
                  {content.options[optKey]}
                </div>
                {isTKP && (
                  <div className="ml-3 font-bold text-gray-500 text-sm">
                    {content.answer_key.tkp_points?.[optKey]} Poin
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Explanation Text */}
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
          <h3 className="font-bold text-yellow-800 mb-2 flex items-center">
            <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"/></svg>
            Kunci & Pembahasan
          </h3>
          <p className="text-gray-700 leading-relaxed whitespace-pre-wrap text-sm md:text-base">
            {content.explanation}
          </p>
        </div>
      </div>

      <div className="bg-gray-50 p-4 border-t border-gray-200 flex justify-between items-center">
        <button
          onClick={onReset}
          className="text-gray-600 hover:text-red-600 font-medium transition"
        >
          Akhiri Sesi
        </button>
        <button
          onClick={onNext}
          className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-8 rounded shadow transition-colors"
        >
          {isLastQuestion ? "Selesai & Ringkasan" : "Lanjut Soal Berikutnya →"}
        </button>
      </div>
    </div>
  );
};

export default ResultCard;

import React, { useState } from 'react';
import { generateQuestionBatch } from './services/geminiService';
import { saveBatchToNeon } from './services/neonService';
import { GeneratedQuestion, AppState } from './types';
import InputSection from './components/InputSection';
import QuestionCard from './components/QuestionCard';
import ResultCard from './components/ResultCard';
import NeonConfigModal from './components/NeonConfigModal';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);

  // Batch State
  const [questionBatch, setQuestionBatch] = useState<GeneratedQuestion[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const [userSelection, setUserSelection] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Neon State
  const [isNeonModalOpen, setIsNeonModalOpen] = useState(false);
  const [neonConnectionString, setNeonConnectionString] = useState('');
  const [isSavingToNeon, setIsSavingToNeon] = useState(false);

  const handleGenerate = async (text: string) => {
    setAppState(AppState.LOADING);
    setErrorMsg('');
    try {
      const data = await generateQuestionBatch(text);
      setQuestionBatch(data.questions);
      setCurrentQuestionIndex(0);
      setAppState(AppState.QUESTION);
    } catch (err: any) {
      setErrorMsg(err.message || 'Terjadi kesalahan saat membuat soal.');
      setAppState(AppState.ERROR);
    }
  };

  const handleAnswer = (option: string) => {
    setUserSelection(option);
    setAppState(AppState.RESULT);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIndex < questionBatch.length - 1) {
        setCurrentQuestionIndex(prev => prev + 1);
        setUserSelection('');
        setAppState(AppState.QUESTION);
    } else {
        setAppState(AppState.BATCH_COMPLETE);
    }
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setQuestionBatch([]);
    setCurrentQuestionIndex(0);
    setUserSelection('');
    setErrorMsg('');
  };

  const handleSaveNeonConfig = (str: string) => {
    setNeonConnectionString(str);
    setIsNeonModalOpen(false);
  };

  const handleSaveToNeon = async () => {
    if (!neonConnectionString) {
        setIsNeonModalOpen(true);
        return;
    }

    setIsSavingToNeon(true);
    try {
        await saveBatchToNeon(neonConnectionString, questionBatch);
        alert('Berhasil menyimpan soal ke Neon DB!');
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSavingToNeon(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 text-white py-4 px-6 shadow-md z-10 sticky top-0">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={handleReset}>
            <div className="w-8 h-8 bg-blue-500 rounded flex items-center justify-center font-bold text-lg">
              S
            </div>
            <div>
              <h1 className="font-bold text-lg leading-tight">CAT BKN Simulator</h1>
              <p className="text-xs text-gray-400">AI-Powered Question Generator</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
                onClick={() => setIsNeonModalOpen(true)}
                className="text-xs text-green-400 border border-green-600 px-2 py-1 rounded hover:bg-green-900 transition flex items-center gap-1"
            >
                <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                {neonConnectionString ? 'DB Configured' : 'Connect Neon DB'}
            </button>
            <div className="text-xs text-gray-400 hidden sm:block">
                Gemini 2.0 Flash Integration
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full p-4 md:p-8">

        {appState === AppState.IDLE && (
          <div className="animate-fade-in-up">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-extrabold text-gray-800 mb-3">
                Latihan SKD Berbasis Isu Terkini
              </h2>
              <p className="text-gray-600 max-w-2xl mx-auto">
                Mesin ini menggunakan AI untuk mengubah berita menjadi <strong>paket 3 soal standar CAT CPNS</strong> (TWK, TIU, TKP) lengkap dengan pembahasan HOTS.
              </p>
            </div>
            <InputSection onGenerate={handleGenerate} isLoading={false} />

            {/* Features Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 text-center">
              <div className="p-4">
                <div className="w-12 h-12 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">W</div>
                <h3 className="font-bold text-gray-800">TWK (Wawasan Kebangsaan)</h3>
                <p className="text-sm text-gray-500 mt-2">Analisis pilar negara dan implementasi Pancasila.</p>
              </div>
              <div className="p-4">
                <div className="w-12 h-12 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">I</div>
                <h3 className="font-bold text-gray-800">TIU (Intelegensia Umum)</h3>
                <p className="text-sm text-gray-500 mt-2">Logika verbal, numerik, dan penalaran analitis.</p>
              </div>
              <div className="p-4">
                <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-3 text-xl font-bold">K</div>
                <h3 className="font-bold text-gray-800">TKP (Karakteristik Pribadi)</h3>
                <p className="text-sm text-gray-500 mt-2">Studi kasus pelayanan publik dan profesionalisme.</p>
              </div>
            </div>
          </div>
        )}

        {appState === AppState.LOADING && (
          <div className="flex flex-col items-center justify-center h-64 animate-pulse">
            <div className="w-16 h-16 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin mb-4"></div>
            <p className="text-gray-600 font-medium">Sedang menganalisis berita...</p>
            <p className="text-xs text-gray-400 mt-2">AI sedang menyusun 3 soal HOTS sesuai kisi-kisi SKD</p>
          </div>
        )}

        {appState === AppState.ERROR && (
          <div className="max-w-xl mx-auto text-center bg-red-50 p-8 rounded-lg border border-red-200">
            <div className="text-red-500 text-5xl mb-4">⚠️</div>
            <h3 className="text-xl font-bold text-red-800 mb-2">Terjadi Kesalahan</h3>
            <p className="text-red-600 mb-6">{errorMsg}</p>
            <button 
              onClick={handleReset}
              className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition"
            >
              Coba Lagi
            </button>
          </div>
        )}

        {appState === AppState.QUESTION && questionBatch.length > 0 && (
          <QuestionCard 
            data={questionBatch[currentQuestionIndex]} 
            currentIndex={currentQuestionIndex}
            totalQuestions={questionBatch.length}
            onAnswer={handleAnswer} 
            onReset={handleReset}
          />
        )}

        {appState === AppState.RESULT && questionBatch.length > 0 && (
          <ResultCard 
            data={questionBatch[currentQuestionIndex]} 
            userSelection={userSelection}
            isLastQuestion={currentQuestionIndex === questionBatch.length - 1}
            onNext={handleNextQuestion}
            onReset={handleReset}
          />
        )}

        {appState === AppState.BATCH_COMPLETE && (
            <div className="max-w-2xl mx-auto text-center animate-fade-in">
                <div className="bg-white rounded-lg shadow-xl p-8 border border-green-200">
                    <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
                        <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                    </div>
                    <h2 className="text-3xl font-bold text-gray-800 mb-4">Sesi Latihan Selesai!</h2>
                    <p className="text-gray-600 mb-8">
                        Anda telah menyelesaikan {questionBatch.length} soal latihan.
                    </p>

                    <div className="flex flex-col sm:flex-row gap-4 justify-center">
                        <button
                            onClick={handleReset}
                            className="px-6 py-3 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition font-medium"
                        >
                            Buat Paket Soal Baru
                        </button>
                        <button
                            onClick={handleSaveToNeon}
                            disabled={isSavingToNeon}
                            className="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition font-medium flex items-center justify-center gap-2"
                        >
                            {isSavingToNeon ? 'Menyimpan...' : 'Simpan ke Neon DB'}
                        </button>
                    </div>
                    {!neonConnectionString && (
                        <p className="text-xs text-gray-400 mt-4">
                            *Anda perlu mengonfigurasi koneksi database di pojok kanan atas untuk menggunakan fitur simpan.
                        </p>
                    )}
                </div>
            </div>
        )}

      </main>

      <NeonConfigModal 
        isOpen={isNeonModalOpen}
        onClose={() => setIsNeonModalOpen(false)}
        onSave={handleSaveNeonConfig}
        savedConnectionString={neonConnectionString}
      />

      <footer className="bg-gray-100 py-6 text-center text-gray-500 text-sm border-t border-gray-200 mt-auto">
        &copy; {new Date().getFullYear()} Simulator SKD AI. Bukan aplikasi resmi BKN.
      </footer>
    </div>
  );
};

export default App;

export interface QuestionMeta {
  news_topic: string;
  question_type: string;
  stimulus_excerpt: string;
}

export interface QuestionOptions {
  A: string;
  B: string;
  C: string;
  D: string;
  E: string;
}

export interface TkpPoints {
  A: number;
  B: number;
  C: number;
  D: number;
  E: number;
}

export interface AnswerKey {
  correct_option: string; // "A" | "B" | "C" | "D" | "E"
  tkp_points: TkpPoints | null;
}

export interface QuestionContent {
  category: 'TWK' | 'TIU' | 'TKP';
  topic: string;
  subtopic: string;
  question_text: string;
  options: QuestionOptions;
  answer_key: AnswerKey;
  explanation: string;
}

export interface GeneratedQuestion {
  meta: QuestionMeta;
  content: QuestionContent;
}

export interface GeneratedQuestionBatch {
  questions: GeneratedQuestion[];
}

export interface NeonConfig {
  connectionString: string;
}

export enum AppState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  GENERATED = 'GENERATED',
  ERROR = 'ERROR'
}

import React from 'react';
