                        const isCorrect = q.content.answer_key.correct_option === key;
                        // Determine background for TKP
                        const tkpPoints = q.content.answer_key.tkp_points?.[key as keyof TkpPoints];
                        const isTkpBest = tkpPoints === 5;

                        let borderClass = 'border-gray-200';
                        let bgClass = 'bg-white';

                        if (q.content.category === 'TKP') {
                            if (isTkpBest) {
                                borderClass = 'border-green-500';
