                                    ? 'bg-green-600 text-white' 
                                    : 'bg-gray-200 text-gray-500'
                                }`}>
                                    {key}
                                </div>
                                <div className="flex-1 text-gray-800 text-sm">
                                    {val}
                                </div>
                                {tkpPoints && (
                                    <div className="text-xs font-bold text-gray-500 ml-2 whitespace-nowrap">({tkpPoints})</div>
                                )}
                            </div>
                        )
                    })}
                </div>

                <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-sm text-gray-700">
                    <div className="flex items-start gap-2">
                        <svg className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        <div>
                            <strong className="block text-blue-900 mb-1">Pembahasan & Kunci Jawaban</strong>
                            <p className="leading-relaxed opacity-90">{q.content.explanation}</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      ))}
    </div>
  );
};

