import { GoogleGenAI, Schema } from "@google/genai";
import { GeneratedQuestionBatch } from "../types";

const BASE_SYSTEM_PROMPT = `# SYSTEM PROMPT — CPNS SKD QUESTION GENERATOR (CAT BKN SIMULATOR)

## PERAN & TUJUAN
Anda adalah **Mesin Simulasi CAT BKN (SKD CPNS)** yang bertugas membuat **3 (tiga) soal latihan berkualitas tinggi** dalam satu paket, berbasis **teks berita/topik terkini** yang diberikan pengguna.

Berita berfungsi sebagai **stimulus/konteks**.

---

## ATURAN GLOBAL (WAJIB)
1. **Output hanya JSON valid**: Output harus berupa objek JSON dengan root key \`"questions"\` yang berisi array 3 soal.
2. **Bahasa**: Bahasa Indonesia baku, gaya soal resmi.
3. **HOTS**: Soal harus menuntut analisis.
4. **Anti-ambigu**: Jawaban benar tunggal (TWK/TIU) atau skoring berjenjang (TKP).
5. **Keamanan & netralitas**: Gunakan framing profesional.

---

## STRUKTUR SOAL (Sama untuk setiap item dalam array)
Lihat aturan kategori TWK/TIU/TKP standar (Nasionalisme, Logika/Numerik, Pelayanan Publik/BerAKHLAK).

---

## SKEMA OUTPUT JSON (WAJIB PERSIS STRUKTURNYA)
\`\`\`json
{
  "questions": [
    {
      "meta": {
        "news_topic": "Ringkasan topik",
        "question_type": "HOTS",
        "stimulus_excerpt": "Kutip 1–2 kalimat inti relevan untuk soal ini."
      },
      "content": {
        "category": "TWK", 
        "topic": "Nasionalisme",
        "subtopic": "Penerapan Pancasila",
        "question_text": "Stem soal...",
        "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
        "answer_key": {
          "correct_option": "A",
          "tkp_points": null
        },
        "explanation": "Pembahasan..."
      }
    },
    { ...soal kedua... },
    { ...soal ketiga... }
  ]
}
\`\`\`
`;

const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = []): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();

  let categoryInstruction = "";
  if (categories.length > 0) {
    categoryInstruction = `\n\nINSTRUKSI KHUSUS: Buat soal HANYA untuk kategori berikut: ${categories.join(', ')}. Distribusikan 3 soal tersebut di antara kategori yang dipilih.`;
  } else {
    categoryInstruction = "\n\nINSTRUKSI KHUSUS: Buat variasi kategori (misal: 1 TWK, 1 TIU, 1 TKP) atau sesuaikan dengan dominasi topik berita.";
  }

  const systemPrompt = BASE_SYSTEM_PROMPT + categoryInstruction;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: newsText,
    config: {
      systemInstruction: systemPrompt,
      responseMimeType: "application/json",
      temperature: 0.7,
    },
  });

  if (!response.text) {
    throw new Error("No response from AI");
  }

  try {
    const data = JSON.parse(response.text) as GeneratedQuestionBatch;

    // Basic validation
    if (!data.questions || !Array.isArray(data.questions) || data.questions.length === 0) {
        throw new Error("Invalid JSON structure: 'questions' array missing or empty.");
    }

    return data;
  } catch (error) {
    console.error("Failed to parse JSON:", response.text);
    throw new Error("Gagal memproses soal dari AI. Silakan coba lagi.");
  }
};

export const getTrendingNews = async (): Promise<string> => {
  const ai = getAiInstance();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: "Cari satu berita utama nasional Indonesia hari ini yang faktual dan serius (terkait kebijakan pemerintah, isu sosial, atau pelayanan publik) yang cocok untuk bahan soal ujian CPNS. Berikan ringkasan naratif 2-3 paragraf yang padat data/fakta.",
    config: {
      tools: [{ googleSearch: {} }],
    },
  });

  const text = response.text || "Tidak dapat menemukan berita trending saat ini.";

  // Extract source URLs from grounding metadata
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const urls = chunks
    .map((chunk: any) => chunk.web?.uri)
    .filter((uri: string | undefined) => uri) as string[];

  // Remove duplicates
  const uniqueUrls = [...new Set(urls)];

  if (uniqueUrls.length > 0) {
    return `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}`;
  }

  return text;
};

