                                    : 'bg-gray-200 text-gray-500'
                                }`}>
                                    {key}
                                </div>
                                <div className="flex-1 text-gray-800 text-sm">
                                    {val}
                                </div>
                                {tkpPoints && (
                                    <div className="text-xs font-bold text-gray-500 ml-2 whitespace-nowrap">({tkpPoints})</div>
                                )}
                            </div>
                        )
                    })}
