import React, { useState, useEffect } from 'react';
import { GeneratedQuestion } from '../types';

interface QuestionCardProps {
  data: GeneratedQuestion;
  currentIndex: number;
  totalQuestions: number;
  onAnswer: (selectedOption: string) => void;
  onReset: () => void;
}

const QuestionCard: React.FC<QuestionCardProps> = ({ data, currentIndex, totalQuestions, onAnswer, onReset }) => {
  const [selected, setSelected] = useState<string | null>(null);

  const { content, meta } = data;

  // Reset selection if data changes
  useEffect(() => {
    setSelected(null);
  }, [data]);

  const handleSubmit = () => {
    if (selected) {
      onAnswer(selected);
    }
  };

  const getCategoryColor = (cat: string) => {
    switch (cat) {
      case 'TWK': return 'bg-red-100 text-red-800 border-red-200';
      case 'TIU': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'TKP': return 'bg-green-100 text-green-800 border-green-200';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg border border-gray-200 overflow-hidden max-w-4xl mx-auto">
      {/* Header Bar */}
      <div className="bg-blue-600 text-white p-4 flex justify-between items-center">
        <div className="font-bold text-lg">SIMULASI CAT BKN</div>
        <div className="flex items-center gap-4">
            <div className="text-sm bg-blue-800 bg-opacity-50 px-3 py-1 rounded border border-blue-400">
                Soal {currentIndex + 1} / {totalQuestions}
            </div>
            <div className="text-sm bg-blue-700 px-3 py-1 rounded">
            Sisa Waktu: --:--
            </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row">
        {/* Left: Question Area */}
        <div className="flex-1 p-6 md:p-8">

          {/* Metadata Badges */}
          <div className="flex flex-wrap gap-2 mb-6">
            <span className={`px-2.5 py-0.5 rounded border text-xs font-bold ${getCategoryColor(content.category)}`}>
              {content.category}
            </span>
            <span className="px-2.5 py-0.5 rounded border bg-gray-100 text-gray-600 border-gray-200 text-xs font-medium">
              Topik: {content.topic}
            </span>
            <span className="px-2.5 py-0.5 rounded border bg-blue-50 text-blue-600 border-blue-100 text-xs font-medium">
              HOTS
            </span>
          </div>

          {/* Question Text */}
          <div className="text-lg text-gray-800 font-medium leading-relaxed mb-8">
            {content.question_text}
          </div>

          {/* Options */}
          <div className="space-y-3">
            {(Object.keys(content.options) as Array<keyof typeof content.options>).map((optKey) => (
              <label 
                key={optKey}
                className={`flex items-start p-4 rounded-lg border-2 cursor-pointer transition-all hover:bg-blue-50
                  ${selected === optKey 
                    ? 'border-blue-600 bg-blue-50' 
                    : 'border-gray-200 bg-white'
                  }`}
              >
                <input
                  type="radio"
                  name="option"
                  value={optKey}
                  checked={selected === optKey}
                  onChange={() => setSelected(optKey)}
                  className="hidden"
                />
                <div className={`flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-full border-2 mr-4 font-bold
                  ${selected === optKey 
                    ? 'bg-blue-600 border-blue-600 text-white' 
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }`}>
                  {optKey}
                </div>
                <div className="pt-0.5 text-gray-700">
                  {content.options[optKey]}
                </div>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Footer Actions */}
      <div className="bg-gray-50 p-4 border-t border-gray-200 flex justify-between items-center">
        <button
          onClick={onReset}
          className="px-4 py-2 text-gray-600 font-medium hover:text-gray-800 transition"
        >
          &larr; Batal & Kembali
        </button>
        <button
          onClick={handleSubmit}
          disabled={!selected}
          className={`px-8 py-2.5 rounded shadow-sm font-bold text-white transition-all
            ${!selected 
              ? 'bg-gray-300 cursor-not-allowed' 
              : 'bg-green-600 hover:bg-green-700 hover:shadow-md'
            }`}
        >
          Kunci Jawaban
        </button>
      </div>
    </div>
  );
};

export default QuestionCard;

import { neon } from "@neondatabase/serverless";
import { GeneratedQuestion } from "../types";

export const saveBatchToNeon = async (connectionString: string, questions: GeneratedQuestion[]): Promise<void> => {
  if (!connectionString) throw new Error("Connection string is empty");

  // Initialize Neon client
  const sql = neon(connectionString);

  try {
    // 1. Ensure Table Exists
    await sql`
      CREATE TABLE IF NOT EXISTS cpns_questions (
        id SERIAL PRIMARY KEY,
        category TEXT NOT NULL,
        topic TEXT,
        question_text TEXT NOT NULL,
        options JSONB NOT NULL,
        answer_key JSONB NOT NULL,
        explanation TEXT,
        news_source TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );
    `;

    // 2. Insert Questions
    for (const q of questions) {
      await sql`
        INSERT INTO cpns_questions (
          category, 
          topic, 
          question_text, 
          options, 
          answer_key, 
          explanation, 
          news_source
        ) VALUES (
          ${q.content.category},
          ${q.content.topic},
          ${q.content.question_text},
          ${JSON.stringify(q.content.options)},
          ${JSON.stringify(q.content.answer_key)},
          ${q.content.explanation},
          ${q.meta.news_topic}
        );
      `;
    }
  } catch (error) {
    console.error("Neon DB Error:", error);
    throw new Error("Gagal menyimpan ke database. Periksa connection string Anda.");
  }
};

import { GoogleGenAI, Schema } from "@google/genai";
import { GeneratedQuestionBatch } from "../types";

const getSystemPrompt = (count: number, categories: string[]) => {
  let categoryInstruction = "";
  if (categories.length > 0) {
    categoryInstruction = `\n\nINSTRUKSI KHUSUS: Buat soal HANYA untuk kategori berikut: ${categories.join(', ')}. Distribusikan ${count} soal tersebut di antara kategori yang dipilih secara merata atau proporsional.`;
  } else {
    categoryInstruction = `\n\nINSTRUKSI KHUSUS: Buat variasi kategori (misal: proporsional TWK, TIU, TKP) untuk total ${count} soal, sesuaikan dengan dominasi topik berita.`;
  }

  return `# SYSTEM PROMPT — CPNS SKD QUESTION GENERATOR (CAT BKN SIMULATOR)

## PERAN & TUJUAN
Anda adalah **Mesin Simulasi CAT BKN (SKD CPNS)** yang bertugas membuat **${count} soal latihan berkualitas tinggi** dalam satu paket, berbasis **teks berita/topik terkini** yang diberikan pengguna.

Berita berfungsi sebagai **stimulus/konteks**.

---

## ATURAN GLOBAL (WAJIB)
1. **Output hanya JSON valid**: Output harus berupa objek JSON dengan root key \`"questions"\` yang berisi array ${count} soal.
2. **Bahasa**: Bahasa Indonesia baku, gaya soal resmi.
3. **HOTS**: Soal harus menuntut analisis.
4. **Anti-ambigu**: Jawaban benar tunggal (TWK/TIU) atau skoring berjenjang (TKP).
5. **Keamanan & netralitas**: Gunakan framing profesional.
6. **INTEGRASI STIMULUS (PENTING)**: Setiap soal **WAJIB** menyertakan narasi ringkas dari berita sebagai pembuka soal. Jangan membuat soal yang bertanya "Berdasarkan berita di atas..." tanpa menyertakan konteks beritanya di dalam teks soal itu sendiri. Soal harus mandiri (self-contained).

---

## STRUKTUR SOAL (Sama untuk setiap item dalam array)
Lihat aturan kategori TWK/TIU/TKP standar (Nasionalisme, Logika/Numerik, Pelayanan Publik/BerAKHLAK).

---

## SKEMA OUTPUT JSON (WAJIB PERSIS STRUKTURNYA)
\`\`\`json
{
  "questions": [
    {
      "meta": {
        "news_topic": "Ringkasan topik",
        "question_type": "HOTS"
      },
      "content": {
        "category": "TWK", 
        "topic": "Nasionalisme",
        "subtopic": "Penerapan Pancasila",
        "question_text": "Tuliskan narasi stimulus/ringkasan berita di sini dahulu secara parafrase. Baru kemudian ajukan pertanyaan intinya...",
        "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
        "answer_key": {
          "correct_option": "A",
          "tkp_points": null
        },
        "explanation": "Pembahasan..."
      }
    }
    // ... ulangi hingga mencapai ${count} soal
  ]
}
\`\`\`
${categoryInstruction}
`;
};

const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = [], count: number = 3): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();

  const systemPrompt = getSystemPrompt(count, categories);

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: newsText,
    config: {
      systemInstruction: systemPrompt,
      responseMimeType: "application/json",
      temperature: 0.7,
    },
  });

  if (!response.text) {
    throw new Error("No response from AI");
  }

  try {
    const data = JSON.parse(response.text) as GeneratedQuestionBatch;

    // Basic validation
    if (!data.questions || !Array.isArray(data.questions) || data.questions.length === 0) {
        throw new Error("Invalid JSON structure: 'questions' array missing or empty.");
    }

    return data;
  } catch (error) {
    console.error("Failed to parse JSON:", response.text);
    throw new Error("Gagal memproses soal dari AI. Silakan coba lagi.");
  }
};

export const getTrendingNews = async (): Promise<string> => {
  const ai = getAiInstance();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: "Cari satu berita utama nasional Indonesia hari ini yang faktual dan serius. Topik harus mencakup isu politik, kebijakan pemerintah, geopolitik Indonesia, atau pelayanan publik yang cocok untuk bahan soal ujian CPNS. Berikan ringkasan naratif 2-3 paragraf yang padat data/fakta.",
    config: {
      tools: [{ googleSearch: {} }],
    },
  });

  const text = response.text || "Tidak dapat menemukan berita trending saat ini.";

  // Extract source URLs from grounding metadata
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const urls = chunks
    .map((chunk: any) => chunk.web?.uri)
    .filter((uri: string | undefined) => uri) as string[];

  // Remove duplicates
  const uniqueUrls = [...new Set(urls)];

  if (uniqueUrls.length > 0) {
    return `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}`;
  }

  return text;
};

