            <button
              type="button"
              onClick={handlePasteSample}
              className="flex-1 sm:flex-none text-sm text-gray-500 hover:text-gray-700 font-medium disabled:opacity-50 underline decoration-dotted"
              disabled={isLoading || isNewsLoading}
            >
              Tempel Contoh
            </button>
          </div>

          <button
            type="submit"
            disabled={isLoading || isNewsLoading || !text.trim() || selectedCategories.length === 0}
            className={`w-full sm:w-auto px-6 py-2.5 rounded-md font-semibold text-white shadow-sm transition-all
              ${isLoading || isNewsLoading || !text.trim() || selectedCategories.length === 0
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-blue-600 hover:bg-blue-700 active:transform active:scale-95'
              }`}
          >
            {isLoading ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Memproses...
              </span>
            ) : (
              'Buat Soal'
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

