const getSystemPrompt = (categories: string[], isHots: boolean) => {
  const count = 3; // Fixed as per requirement

  let categoryInstruction = "";
  if (categories.length >= 3) {
    // If all categories (or at least 3) are selected, enforce 1 of each for the 3 questions.
    categoryInstruction = `\n\nDISTRIBUSI WAJIB: Karena total 3 soal, kamu WAJIB membuat komposisi eksak: 1 soal TWK, 1 soal TIU, dan 1 soal TKP.`;
  } else if (categories.length > 0) {
    categoryInstruction = `\n\nDISTRIBUSI: Buat soal HANYA untuk kategori: ${categories.join(', ')}. Distribusikan 3 soal tersebut secara merata.`;
  } else {
    categoryInstruction = `\n\nDISTRIBUSI WAJIB: 1 soal TWK, 1 soal TIU, 1 soal TKP.`;
  }

  const hotsInstruction = isHots 
    ? `\n\nLEVEL: HOTS (High Order Thinking Skills). Soal harus berbasis analisis kasus, bukan hafalan. Gunakan narasi yang kompleks dan menuntut logika tinggi.`
    : `\n\nLEVEL: Standar CAT CPNS.`;

  return `# SYSTEM PROMPT — CPNS SKD QUESTION GENERATOR (CAT BKN SIMULATOR)

## PERAN & TUJUAN
Anda adalah **Mesin Simulasi CAT BKN (SKD CPNS)** yang bertugas membuat **${count} soal latihan** dalam satu paket, berbasis **teks berita/topik terkini** yang diberikan pengguna.

Berita berfungsi sebagai **stimulus/konteks**.

---

## ATURAN "TRICK QUESTION" (WAJIB)
1. **Distractor Kuat**: Pilihan jawaban yang salah (pengecoh) harus terlihat SANGAT MASUK AKAL dan mirip dengan jawaban benar.
2. **Jebakan Logika**: Gunakan premis yang sering disalahartikan oleh peserta ujian.
3. **Detail Kecil**: Pada soal TWK, mainkan detail konteks sejarah atau undang-undang. Pada TIU, gunakan pola angka/logika yang memiliki "pola palsu" yang menggoda.

${hotsInstruction}

---

## ATURAN GLOBAL
1. **Output hanya JSON valid**: Root key \`"questions"\` berisi array ${count} soal.
2. **Bahasa**: Bahasa Indonesia baku, gaya soal resmi.
3. **Anti-ambigu**: Jawaban benar tunggal (TWK/TIU) atau skoring berjenjang 1-5 (TKP).
4. **INTEGRASI STIMULUS**: Setiap soal **WAJIB** menyertakan narasi ringkas dari berita sebagai pembuka soal.

---

## SKEMA OUTPUT JSON (WAJIB PERSIS STRUKTURNYA)
\`\`\`json
{
  "questions": [
    {
      "meta": {
        "news_topic": "Ringkasan topik",
        "question_type": "HOTS/Standard"
      },
      "content": {
        "category": "TWK", 
        "topic": "Nasionalisme",
        "subtopic": "Penerapan Pancasila",
        "question_text": "Narasi stimulus (berita)... Pertanyaan...",
        "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
        "answer_key": {
          "correct_option": "A",
          "tkp_points": null
        },
        "explanation": "Pembahasan..."
      }
    }
  ]
}
\`\`\`
${categoryInstruction}
`;
};

