export const getTrendingNews = async (): Promise<string> => {
  const ai = getAiInstance();

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: "Cari satu berita nasional Indonesia yang paling trending dalam 1 bulan terakhir. Topik prioritas meliputi: kasus korupsi besar (controversial), bencana alam/non-alam, kebijakan pemerintah strategis, atau isu politik/geopolitik panas. Berita harus faktual, serius, dan memiliki bobot data untuk dijadikan stimulus soal ujian CPNS. Berikan ringkasan naratif 2-3 paragraf.",
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "Tidak dapat menemukan berita trending saat ini.";

    // Extract source URLs from grounding metadata
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const urls = chunks
      .map((chunk: any) => chunk.web?.uri)
      .filter((uri: string | undefined) => uri) as string[];

    // Remove duplicates
    const uniqueUrls = [...new Set(urls)];

    if (uniqueUrls.length > 0) {
      return `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}`;
    }

    return text;

  } catch (error: any) {
    console.warn("Google Search failed, falling back to internal knowledge:", error);

    // Fallback if Google Search is not allowed (403 Permission Denied)
    if (error.message?.includes('403') || error.status === 'PERMISSION_DENIED') {
        try {
             const fallbackResponse = await ai.models.generateContent({
                model: MODEL_NAME,
                contents: "Buat satu ringkasan berita simulasi (berdasarkan data nyata yang kamu ketahui) tentang isu nasional Indonesia (korupsi/bencana/kebijakan) yang cocok untuk soal CPNS. Tulis seolah-olah ini berita terkini. Berikan 2-3 paragraf.",
            });
            return (fallbackResponse.text || "") + "\n\n(Catatan: Berita ini digenerate dari pengetahuan internal AI karena akses Pencarian dibatasi)";
        } catch (fallbackError) {
             throw new Error("Gagal mengambil berita (Akses Ditolak).");
        }
    }

    throw new Error("Gagal mencari berita trending.");
  }
};

import { neon } from "@neondatabase/serverless";
import { GeneratedQuestion } from "../types";

export const saveBatchToNeon = async (connectionString: string, questions: GeneratedQuestion[]): Promise<void> => {
  if (!connectionString) throw new Error("Connection string is empty");

  // Initialize Neon client
  const sql = neon(connectionString);

  try {
    // 1. Initialize Schema (Create Tables)
    // We create the normalized schema as requested.
    // Using IF NOT EXISTS to prevent errors on subsequent runs.

    await sql`
      CREATE EXTENSION IF NOT EXISTS "pgcrypto";

      CREATE TABLE IF NOT EXISTS questions (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        category VARCHAR(10) NOT NULL CHECK (category IN ('TIU', 'TWK', 'TKP')),
        topic VARCHAR(255),
        subtopic VARCHAR(255),
        question_text TEXT NOT NULL,
        difficulty INT DEFAULT 3,
        time_limit_seconds INT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS question_options (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        question_id UUID REFERENCES questions(id) ON DELETE CASCADE,
        option_key CHAR(1) NOT NULL,
        option_text TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS question_answers (
        question_id UUID PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
        correct_option CHAR(1) NOT NULL
      );

      CREATE TABLE IF NOT EXISTS tkp_option_scores (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        question_id UUID REFERENCES questions(id) ON DELETE CASCADE,
        option_key CHAR(1) NOT NULL,
        score INT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS question_explanations (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        question_id UUID REFERENCES questions(id) ON DELETE CASCADE,
        tier VARCHAR(50) DEFAULT 'free',
        explanation_text TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS question_meta (
        question_id UUID PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
        source VARCHAR(255),
        notes TEXT
      );
    `;

    // 2. Insert Questions
    for (const q of questions) {
      // A. Insert Core Question
      // Note: GeneratedQuestion uses uppercase keys (A,B,C), we convert to lowercase (a,b,c) for DB as per requirement

      const [insertedQuestion] = await sql`
        INSERT INTO questions (
          category, 
          topic, 
          subtopic, 
          question_text, 
          difficulty
        ) VALUES (
          ${q.content.category},
          ${q.content.topic},
          ${q.content.subtopic},
          ${q.content.question_text},
          3
        )
        RETURNING id;
      `;

      const questionId = insertedQuestion.id;

      // B. Insert Options
      // q.content.options is {A: "...", B: "..."}
      for (const [key, text] of Object.entries(q.content.options)) {
        const lowerKey = key.toLowerCase();
        await sql`
          INSERT INTO question_options (question_id, option_key, option_text)
          VALUES (${questionId}, ${lowerKey}, ${text});
        `;
      }

      // C. Insert Answer / Scores
      if (q.content.category === 'TWK' || q.content.category === 'TIU') {
        // Enforce logic: Question Answers table only for TIU/TWK
        const correctKey = q.content.answer_key.correct_option.toLowerCase();
        await sql`
          INSERT INTO question_answers (question_id, correct_option)
          VALUES (${questionId}, ${correctKey});
        `;
      } else if (q.content.category === 'TKP') {
        // Enforce logic: TKP Option Scores table only for TKP
        if (q.content.answer_key.tkp_points) {
           for (const [key, score] of Object.entries(q.content.answer_key.tkp_points)) {
             const lowerKey = key.toLowerCase();
             await sql`
               INSERT INTO tkp_option_scores (question_id, option_key, score)
               VALUES (${questionId}, ${lowerKey}, ${score});
             `;
           }
        }
      }

      // D. Insert Explanation
      await sql`
        INSERT INTO question_explanations (question_id, tier, explanation_text)
        VALUES (${questionId}, 'free', ${q.content.explanation});
      `;

      // E. Insert Meta
      // Using news_topic as source
      await sql`
        INSERT INTO question_meta (question_id, source)
        VALUES (${questionId}, ${q.meta.news_topic});
      `;
    }
  } catch (error) {
    console.error("Neon DB Error:", error);
    throw new Error("Gagal menyimpan ke database. Terjadi kesalahan pada struktur data atau koneksi.");
  }
};

